"""it — quran_b."""

T = {
"quran_081": ("Su cosa si interrogano gli uomini, all'inizio della sura An-Naba?", ["Il grande annuncio", "La pioggia", "Le stelle", "I raccolti"], "«Su cosa si interrogano a vicenda? Sul grande annuncio.»"),
"quran_082": ("Che cosa significa «Al-Qari'ah», il titolo della sura 101?", ["La Percotente", "L'alba", "La carovana", "La montagna"], "«La Percotente! Che cos'è la Percotente? E chi ti farà comprendere cos'è la Percotente?» — è un nome dell'Ultimo Giorno."),
"quran_083": ("Nella sura Al-Qari'ah, che cosa attende colui la cui bilancia sarà leggera?", ["Un abisso (Hawiyah) come dimora", "Un giardino", "Una sorgente", "Una casa"], "«Quanto a colui le cui bilance saranno leggere, avrà per dimora un abisso.»"),
"quran_084": ("Contro che cosa mette in guardia la sura At-Takathur?", ["La gara nell'accumulare, che distoglie", "I viaggi", "La fame", "Il silenzio"], "«Vi distrae la gara per accumulare, finché visitate le tombe.»"),
"quran_085": ("Contro chi si apre la sura Al-Humazah con «Guai a…»?", ["Ogni diffamatore e maldicente", "Il viaggiatore", "Il dormiente", "Il povero"], "«Guai a ogni diffamatore maldicente, che accumula ricchezze e le conta.»"),
"quran_086": ("Che cosa chiede la sura Quraysh ai Quraysh, in cambio dei viaggi d'inverno e d'estate?", ["Adorare il Signore di questa Casa, che li ha nutriti e messi al sicuro", "Costruire mura", "Cessare il commercio", "Partire per lo Yemen"], "«Adorino dunque il Signore di questa Casa, che li ha preservati dalla fame e li ha messi al riparo dalla paura.»"),
"quran_087": ("Con quale domanda si apre la sura Ash-Sharh?", ["«Non ti abbiamo forse aperto il petto?»", "«Non hai visto?»", "«Chi ti ha creato?»", "«Dove vai?»"], "«Non ti abbiamo forse aperto il petto?»"),
"quran_088": ("Su che cosa giura Allah all'inizio della sura At-Tin?", ["Sul fico, l'olivo, il monte Sinai e questa città sicura", "Sulla notte e sul giorno", "Sulle stelle", "Sul mare"], "«Per il fico e per l'olivo, per il monte Sinai e per questa città sicura.»"),
"quran_089": ("Come descrive la sura At-Tin la creazione dell'essere umano?", ["Nella forma migliore", "Debole e piccolo", "Dal fuoco", "Dalla luce"], "«In verità abbiamo creato l'uomo nella forma migliore.»"),
"quran_090": ("Su quale città giura Allah all'inizio della sura Al-Balad?", ["La Mecca, dove dimorava il Profeta ﷺ", "Medina", "Gerusalemme", "Ta'if"], "«Lo giuro per questa città, e tu sei un abitante di questa città.»"),
"quran_091": ("Qual è l'«erta scoscesa» che descrive la sura Al-Balad?", ["Liberare uno schiavo, nutrire un orfano o un bisognoso in un giorno di fame", "Attraversare il deserto", "Scalare una montagna", "Attraversare il mare"], "«E chi ti farà comprendere cos'è l'erta? È liberare uno schiavo, o nutrire, in un giorno di carestia, un parente orfano o un povero prostrato dalla miseria.»"),
"quran_092": ("Su che cosa giura Allah all'inizio della sura Al-Layl?", ["Sulla notte quando avvolge e sul giorno quando appare", "Sul mare e sul monte", "Sul fico e sull'olivo", "Sul calamo"], "«Per la notte quando avvolge, per il giorno quando risplende… in verità i vostri sforzi divergono.»"),
"quran_093": ("Con quale ordine si apre la sura Al-A'la?", ["«Glorifica il nome del tuo Signore, l'Altissimo»", "«Leggi»", "«Alzati»", "«Ascolta»"], "«Glorifica il nome del tuo Signore, l'Altissimo.»"),
"quran_094": ("Di che cosa parla l'inizio della sura Al-Ghashiyah?", ["L'evento avvolgente: l'Ultimo Giorno", "Un viaggio", "Un mercato", "Una battaglia"], "«Ti è giunta notizia dell'Avvolgente?»"),
"quran_095": ("Su quale creatura invita a riflettere la sura Al-Ghashiyah?", ["Il cammello, e come è stato creato", "Il leone", "L'aquila", "Il pesce"], "«Non considerano i cammelli, come sono stati creati?»"),
"quran_096": ("Su che cosa giura Allah all'inizio della sura Al-Buruj?", ["Sul cielo dalle costellazioni", "Sulla terra", "Sui fiumi", "Sulle nuvole"], "«Per il cielo dalle costellazioni, e per il Giorno promesso.»"),
"quran_097": ("A che cosa si riferisce «At-Tariq», il titolo della sura 86?", ["L'astro notturno che trafigge", "La porta", "La strada", "Il tuono"], "«Per il cielo e per l'astro notturno — e chi ti farà comprendere cos'è l'astro notturno? È la stella che trafigge le tenebre.»"),
"quran_098": ("Quale evento descrive l'inizio della sura Az-Zalzalah?", ["La terra scossa dal suo terremoto", "Una pioggia torrenziale", "Un vento violento", "Un'eclissi"], "«Quando la terra sarà scossa dal suo terremoto, e la terra rigetterà i suoi fardelli.»"),
"quran_099": ("Quale misura fissa la fine della sura Az-Zalzalah per le opere?", ["Il peso di un atomo, di bene come di male", "Uno staio", "Un anno", "Una mano"], "«Chi avrà fatto un bene, foss'anche del peso di un atomo, lo vedrà; e chi avrà fatto un male, foss'anche del peso di un atomo, lo vedrà.»"),
"quran_100": ("A che cosa si riferisce «Al-'Adiyat», il titolo della sura 100?", ["I corsieri che galoppano ansimando", "I venti", "Le onde", "Le nuvole"], "«Per i corsieri ansimanti, che fanno sprizzare scintille, che caricano all'alba.»"),
"quran_101": ("Come descrive la sura Al-Baqarah il Libro nel suo secondo versetto?", ["Un libro su cui non vi è dubbio, guida per i timorati", "Un libro di storia", "Una raccolta di poemi", "Un libro di sole leggi"], "«Questo è il Libro su cui non vi è dubbio, una guida per i timorati.»"),
"quran_102": ("Quale versetto promette la conservazione del Monito rivelato?", ["«In verità siamo Noi ad aver fatto scendere il Monito, e in verità Noi ne siamo i custodi»", "«Nessuno lo leggerà»", "«Sarà dimenticato»", "«Sarà nascosto»"], "«In verità siamo Noi ad aver fatto scendere il Corano, e in verità Noi ne siamo i custodi.»"),
"quran_103": ("Quale argomento porta il Corano sulla propria assenza di contraddizioni?", ["Se venisse da altri che Allah, vi troverebbero molte contraddizioni", "Che è breve", "Che è in arabo", "Che è antico"], "«Non meditano dunque sul Corano? Se provenisse da altri che Allah, vi troverebbero molte contraddizioni.»"),
"quran_104": ("Che cosa dice il Corano che sarebbe accaduto a una montagna, se fosse stato rivelato su di essa?", ["Si sarebbe umiliata e spaccata per il timore di Allah", "Avrebbe brillato", "Si sarebbe spostata", "Sarebbe divenuta verde"], "«Se avessimo fatto scendere questo Corano su una montagna, l'avresti vista umiliarsi e spaccarsi per il timore di Allah.»"),
"quran_105": ("Come ordina il Corano di essere recitato, nella sura Al-Muzzammil?", ["In modo misurato e distinto (tartil)", "Il più velocemente possibile", "In silenzio", "Cantando"], "«E recita il Corano con cura misurata.»"),
"quran_106": ("Che cosa bisogna fare quando il Corano viene recitato, secondo la sura Al-A'raf?", ["Ascoltare e tacere", "Rispondere ad alta voce", "Uscire", "Scrivere"], "«Quando si recita il Corano, prestate attenzione e state in silenzio, affinché vi sia usata misericordia.»"),
"quran_107": ("Che cosa ordina il Corano di dire prima di iniziare a leggerlo?", ["Cercare rifugio in Allah contro Satana il lapidato", "Contare i versetti", "Dire l'abluzione ad alta voce", "Recitare l'ultimo versetto"], "«Quando leggi il Corano, cerca rifugio in Allah contro Satana il lapidato.»"),
"quran_108": ("Perché il Libro è stato fatto scendere, secondo la sura Sad?", ["Affinché se ne meditino i versetti e i dotati d'intelletto ne siano ammoniti", "Perché fosse copiato", "Perché fosse contato", "Perché fosse nascosto"], "«È un Libro benedetto che abbiamo fatto scendere su di te, affinché ne meditino i versetti.»"),
"quran_109": ("Quale sfida lancia la sura Al-Isra agli uomini e ai jinn insieme?", ["Produrre qualcosa di simile a questo Corano, foss'anche aiutandosi a vicenda", "Attraversare i cieli", "Contare le stelle", "Costruire una città"], "«Se gli uomini e i jinn si riunissero per produrre qualcosa di simile a questo Corano, non ci riuscirebbero, quand'anche si aiutassero a vicenda.»"),
"quran_110": ("Quale invocazione insegna il Corano riguardo alla scienza?", ["«Signore, accresci la mia scienza»", "«Signore, dammi ricchezza»", "«Signore, allunga la mia vita»", "«Signore, aprimi le strade»"], "«E di': Signore, accresci la mia scienza.»"),
"quran_111": ("Come descrive la sura Az-Zumar il migliore dei discorsi rivelati?", ["Un Libro dalle parti simili e ripetute, al quale la pelle rabbrividisce", "Un libro breve", "Un libro di leggi", "Un libro in versi"], "«Allah ha fatto scendere il più bello dei discorsi: un Libro coerente e ripetitivo, al quale rabbrividisce la pelle di coloro che temono il loro Signore.»"),
"quran_112": ("A che cosa paragona il Corano una buona parola, nella sura Ibrahim?", ["A un albero buono, dalla radice salda e dai rami nel cielo", "A un fiume", "A una montagna", "A una stella"], "«Una buona parola è come un albero buono, la cui radice è salda e i cui rami sono nel cielo; dà il suo frutto in ogni tempo.»"),
"quran_113": ("A che cosa paragona la sura Ar-Ra'd la verità e la falsità?", ["Alla schiuma che il torrente porta via, e a ciò che giova agli uomini e resta", "A due montagne", "A due città", "A due carovane"], "«Quanto alla schiuma, se ne va come scoria; ma ciò che giova agli uomini resta sulla terra.»"),
"quran_114": ("Con che cosa i cuori trovano quiete, secondo la sura Ar-Ra'd?", ["Con il ricordo di Allah", "Con la ricchezza", "Con i viaggi", "Con il sonno"], "«In verità, i cuori si acquietano nel ricordo di Allah.»"),
"quran_115": ("Che cosa dice la sura Al-Kahf dell'inchiostro necessario a scrivere le parole di Allah?", ["Il mare si esaurirebbe prima delle parole del suo Signore", "Basterebbe un calamaio", "Basterebbe una notte", "Basterebbero sette calami"], "«Se il mare fosse inchiostro per le parole del mio Signore, il mare si esaurirebbe prima che si esaurissero le parole del mio Signore.»"),
"quran_116": ("Quanti mari, secondo la sura Luqman, non basterebbero comunque a esaurire le parole di Allah?", ["Sette mari in aggiunta, e non basterebbero ancora", "Uno", "Tre", "Dodici"], "«Se tutti gli alberi della terra fossero calami e il mare inchiostro, rifornito da altri sette mari, non si esaurirebbero le parole di Allah.»"),
"quran_117": ("Quale obiezione, dice il Corano, sarebbe stata sollevata se fosse stato rivelato in una lingua straniera a un messaggero arabo?", ["«Perché i suoi versetti non sono spiegati in dettaglio?»", "«È troppo breve»", "«È troppo lungo»", "«Non ha titolo»"], "«Se ne avessimo fatto un Corano in lingua straniera, avrebbero detto: “Perché i suoi versetti non sono spiegati chiaramente?”»"),
"quran_118": ("Verso che cosa guida il Corano, secondo la sura Al-Isra?", ["Verso ciò che è più retto", "Verso la ricchezza", "Verso il potere", "Verso il riposo"], "«In verità questo Corano guida a ciò che è più retto, e annuncia ai credenti che compiono il bene una grande ricompensa.»"),
"quran_119": ("Come descrive la sura Yunus ciò che è disceso dal Signore?", ["Un'esortazione, una guarigione per ciò che è nei petti, guida e misericordia", "Un rendiconto", "Un decreto regale", "Un trattato"], "«O uomini, vi è giunta un'esortazione dal vostro Signore, una guarigione per ciò che è nei petti, una guida e una misericordia per i credenti.»"),
"quran_120": ("Come descrive la sura Al-Baqarah il ruolo del Corano come criterio?", ["Guida per gli uomini, prove chiare e Discrimine", "Un libro di conti", "Una raccolta di racconti", "Un codice penale"], "«Il mese di Ramadan, nel quale è stato fatto scendere il Corano, guida per gli uomini e prove chiare della guida e del Discrimine.»"),
"quran_121": ("Su che cosa giura Allah all'inizio della sura Qaf?", ["Sul glorioso Corano", "Sulla montagna", "Sul vento", "Sull'alba"], "«Qaf. Per il glorioso Corano.»"),
"quran_122": ("A che cosa si riferisce «Al-Mursalat», il titolo della sura 77?", ["Coloro che sono inviati, uno dopo l'altro", "Le carovane", "Le stelle", "I fiumi"], "«Per gli inviati in successione, uno dopo l'altro.»"),
"quran_123": ("Quale registro nomina la sura Al-Mutaffifin per i pii?", ["'Illiyyun", "Sijjin", "Al-Lawh", "Az-Zabur"], "«Il registro dei pii è in 'Illiyyun… un libro inscritto, che testimoniano gli angeli ravvicinati.»"),
"quran_124": ("Con quale evento si apre la sura Al-Inshiqaq?", ["Il cielo che si fende", "Il mare che straripa", "La terra che rinverdisce", "Il sole che sorge"], "«Quando il cielo si fenderà e ascolterà il suo Signore, come deve.»"),
"quran_125": ("Con quale segno si apre la sura At-Takwir?", ["Il sole avvolto nelle tenebre", "La luna spaccata", "Il vento che si leva", "Il tuono"], "«Quando il sole sarà avvolto, e quando le stelle cadranno perdendo il loro splendore.»"),
"quran_126": ("Che cosa dice l'ultimo versetto della sura Al-Baqarah sul carico imposto a un'anima?", ["Allah non impone a un'anima più di quanto possa sopportare", "Ogni anima porta il doppio", "Nessuno è messo alla prova", "Tutti i carichi sono uguali"], "«Allah non impone a nessuna anima al di là delle sue capacità.»"),
"quran_127": ("A che cosa paragona il Corano la spesa sulla via di Allah?", ["A un chicco che fa crescere sette spighe da cento chicchi ciascuna", "A una pietra", "A un pozzo", "A una lampada"], "«Coloro che spendono i loro beni sulla via di Allah sono come un chicco che fa nascere sette spighe, e in ogni spiga vi sono cento chicchi.»"),
"quran_128": ("A che cosa è paragonata l'elemosina annullata dal rinfaccio e dall'offesa?", ["A una roccia coperta di terra, che un acquazzone lascia nuda", "A un albero da frutto", "A una sorgente", "A una casa"], "«Il suo esempio è quello di una roccia liscia coperta di terra, che un acquazzone lascia nuda.»"),
"quran_129": ("A che cosa paragona il Corano le opere dei miscredenti nella sura An-Nur?", ["A un miraggio nella pianura, che l'assetato prende per acqua", "A una montagna", "Alla pioggia", "A un giardino"], "«Quanto a coloro che non credono, le loro opere sono come un miraggio in una pianura: l'assetato crede che sia acqua, ma quando vi giunge non trova nulla.»"),
"quran_130": ("Quale domanda apre la sura Al-'Ankabut, dopo le lettere isolate?", ["«Gli uomini credono che li si lascerà dire “crediamo” senza essere messi alla prova?»", "«Dove sono i cieli?»", "«Chi ha creato il mare?»", "«Che farete domani?»"], "«Gli uomini credono che li si lascerà dire “crediamo” senza che siano messi alla prova?»"),
"quran_131": ("Come descrive la sura Fatir gli angeli nel suo primo versetto?", ["Messaggeri dotati di ali, a due, a tre e a quattro", "Creati d'argilla", "Di numero sconosciuto", "Simili agli esseri umani"], "«Lode ad Allah, Creatore dei cieli e della terra, che ha fatto degli angeli messaggeri dotati di due, tre o quattro ali.»"),
"quran_132": ("Quale segno menziona la sura Ar-Rum riguardo agli sposi?", ["Che Egli ha posto tra loro affetto e misericordia", "Che vivono separati", "Che lavorano insieme", "Che viaggiano"], "«Fra i Suoi segni vi è che ha creato per voi, dalle vostre stesse persone, delle spose perché trovaste quiete presso di loro, e ha posto tra voi affetto e misericordia.»"),
"quran_133": ("Quali due segni nomina la sura Ar-Rum subito dopo la creazione dei cieli e della terra?", ["La diversità delle lingue e dei colori", "Il giorno e la notte", "Il vento e la pioggia", "Il mare e la montagna"], "«Fra i Suoi segni vi è la creazione dei cieli e della terra, e la diversità delle vostre lingue e dei vostri colori.»"),
"quran_134": ("Da che cosa, secondo la sura Al-Anbiya, Allah ha fatto ogni cosa vivente?", ["Dall'acqua", "Dal fuoco", "Dalla pietra", "Dall'aria"], "«E dall'acqua abbiamo fatto ogni cosa vivente. Non crederanno dunque?»"),
"quran_135": ("Quale argomento porta il Corano contro una pluralità di divinità, nella sura Al-Anbiya?", ["Se vi fossero altre divinità oltre ad Allah, i cieli e la terra sarebbero in rovina", "Si nasconderebbero", "Tacerebbero", "Sparirebbero"], "«Se nei cieli e sulla terra vi fossero altre divinità oltre ad Allah, entrambi andrebbero in rovina.»"),
"quran_136": ("Quali tre cose ordina Allah secondo il versetto 16:90?", ["La giustizia, la benevolenza e il dare ai parenti", "Il digiuno, la preghiera e il pellegrinaggio", "Il commercio, il viaggio e la scrittura", "Il silenzio, la pazienza e il ritiro"], "«In verità Allah ordina la giustizia, la benevolenza e la generosità verso i parenti.»"),
"quran_137": ("Da che cosa esce, secondo la sura An-Nahl, una bevanda dai colori diversi in cui vi è guarigione per gli uomini?", ["Dal ventre delle api", "Dal mare", "Dalle palme", "Dalle sorgenti di montagna"], "«Dal loro ventre esce una bevanda dai colori diversi, in cui vi è guarigione per gli uomini.»"),
"quran_138": ("Come si apre la sura Ar-Rahman?", ["«Il Compassionevole ha insegnato il Corano»", "«Per la notte»", "«Lode ad Allah»", "«Leggi»"], "«Il Compassionevole ha insegnato il Corano, ha creato l'uomo e gli ha insegnato l'eloquenza.»"),
"quran_139": ("In quanti gruppi divide la sura Al-Waqi'ah gli uomini nell'Ultimo Giorno?", ["Tre", "Due", "Quattro", "Sette"], "«E sarete divisi in tre gruppi: i compagni della destra, i compagni della sinistra e i precursori.»"),
"quran_140": ("A che cosa paragona il Corano coloro che portano la Torah senza metterla in pratica?", ["A un asino carico di libri", "A un uccello", "A una montagna", "A una nave"], "«Coloro cui fu affidata la Torah e che poi non se ne fecero carico somigliano a un asino carico di libri.»"),
"quran_141": ("Quale donna il Corano propone come esempio ai credenti, citando la sua richiesta di una casa presso Allah?", ["La moglie di Faraone", "La regina di Saba", "La moglie di Nuh", "La moglie di Lut"], "«E Allah propone a esempio, per coloro che credono, la moglie di Faraone, quando disse: “Signore, costruiscimi presso di Te una casa nel Paradiso.”»"),
"quran_142": ("Con quale altro nome è spesso conosciuta la sura Al-Ikhlas, dal suo tema?", ["La sura dell'unicità (at-tawhid)", "La sura del viaggio", "La sura della luce", "La sura del bottino"], "Al-Ikhlas, «il culto puro», è chiamata anche sura del tawhid, poiché descrive Allah come l'Unico."),
"quran_143": ("Che cosa nega il terzo versetto della sura Al-Ikhlas?", ["Che Egli abbia generato o sia stato generato", "Che sia potente", "Che ascolti", "Che crei"], "«Non ha generato e non è stato generato.»"),
"quran_144": ("Contro che cosa si cerca rifugio nella sura An-Nas?", ["Il tentatore furtivo, tra i jinn e gli uomini", "La tempesta", "La malattia", "La povertà"], "«…contro il male del sussurratore furtivo, che sussurra nei petti degli uomini, che sia dai jinn o dagli uomini.»"),
"quran_145": ("Quanti mali distinti nomina la sura Al-Falaq dopo «il male di ciò che ha creato»?", ["Tre: la notte che si addensa, le soffiatrici sui nodi e l'invidioso", "Uno", "Cinque", "Sette"], "«…dal male dell'oscurità quando si addensa, dal male delle soffiatrici sui nodi, e dal male dell'invidioso quando invidia.»"),
"quran_146": ("Quale versetto di Al-Fatihah esprime il cuore dell'adorazione e della richiesta d'aiuto?", ["«Te solo adoriamo e a Te solo chiediamo aiuto»", "«Lode ad Allah»", "«Guidaci»", "«Sovrano del Giorno del Giudizio»"], "«Te solo adoriamo e a Te solo chiediamo aiuto.»"),
"quran_147": ("Quale richiesta chiude la sura Al-Fatihah?", ["Essere guidati sulla retta via, la via di coloro che sono stati colmati di favore", "La ricchezza", "La vittoria", "Una lunga vita"], "«Guidaci sulla retta via, la via di coloro che hai colmato di favore.»"),
"quran_148": ("Quali due tipi di versetti distingue la sura Al-'Imran?", ["I versetti chiari (muhkamat) e i versetti ambigui (mutashabihat)", "I lunghi e i brevi", "I meccani e i medinesi", "I recitati e gli scritti"], "«È Lui che ha fatto scendere su di te il Libro: vi sono versetti espliciti, che sono la base del Libro, e altri ambigui.»"),
"quran_149": ("Quale principio enuncia il versetto 2:106 sui versetti sostituiti?", ["Allah ne apporta uno migliore o simile", "Sono cancellati senza sostituzione", "Sono dimenticati", "Sono riscritti dagli uomini"], "«Non abroghiamo un versetto, né lo facciamo dimenticare, senza portarne uno migliore o simile.»"),
"quran_150": ("Di che cosa si lamenterà il Messaggero ﷺ presso il suo Signore, secondo la sura Al-Furqan?", ["Che il suo popolo ha abbandonato questo Corano", "Che è stanco", "Che è solo", "Che è povero"], "«E il Messaggero dirà: “Signore, il mio popolo ha in verità abbandonato questo Corano.”»"),
}
